import{_ as r,V as o,W as t,a0 as i,X as a,Y as e,Z as l}from"./framework-828e3e61.js";const n={},d=a("h1",{id:"《深入理解java虚拟机》笔记",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#《深入理解java虚拟机》笔记","aria-hidden":"true"},"#"),e(" 《深入理解java虚拟机》笔记")],-1),h=a("h1",{id:"java-内存区域详解",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#java-内存区域详解","aria-hidden":"true"},"#"),e(" Java 内存区域详解")],-1),E=l('<ul><li><a href="#java-%E5%86%85%E5%AD%98%E5%8C%BA%E5%9F%9F%E8%AF%A6%E8%A7%A3">Java 内存区域详解</a><ul><li><a href="#jvm-%E8%BF%90%E8%A1%8C%E6%97%B6%E7%9A%84%E6%95%B0%E6%8D%AE%E5%8C%BA%E5%9F%9F">JVM 运行时的数据区域</a><ul><li><a href="#%E7%A8%8B%E5%BA%8F%E8%AE%A1%E6%95%B0%E5%99%A8">程序计数器</a></li><li><a href="#java-%E8%99%9A%E6%8B%9F%E6%9C%BA%E6%A0%88">Java 虚拟机栈</a></li><li><a href="#%E6%9C%AC%E5%9C%B0%E6%96%B9%E6%B3%95%E6%A0%88">本地方法栈</a></li><li><a href="#java-%E5%A0%86">Java 堆</a></li><li><a href="#%E6%96%B9%E6%B3%95%E5%8C%BA">方法区</a></li><li><a href="#%E7%9B%B4%E6%8E%A5%E5%86%85%E5%AD%98">直接内存</a></li></ul></li><li><a href="#hotspot-%E8%99%9A%E6%8B%9F%E6%9C%BA%E5%A0%86%E4%B8%AD%E7%9A%84%E5%AF%B9%E8%B1%A1">HotSpot 虚拟机堆中的对象</a><ul><li><a href="#%E5%AF%B9%E8%B1%A1%E7%9A%84%E5%88%9B%E5%BB%BA%E9%81%87%E5%88%B0%E4%B8%80%E6%9D%A1-new-%E6%8C%87%E4%BB%A4%E6%97%B6">对象的创建（遇到一条 new 指令时）</a></li><li><a href="#%E5%AF%B9%E8%B1%A1%E7%9A%84%E5%86%85%E5%AD%98%E5%B8%83%E5%B1%80">对象的内存布局</a></li><li><a href="#%E5%AF%B9%E8%B1%A1%E7%9A%84%E8%AE%BF%E9%97%AE">对象的访问</a><ul><li><a href="#%E5%8F%A5%E6%9F%84%E8%AE%BF%E9%97%AE">句柄访问</a></li><li><a href="#%E7%9B%B4%E6%8E%A5%E6%8C%87%E9%92%88%E8%AE%BF%E9%97%AE">直接指针访问</a></li></ul></li></ul></li></ul></li></ul>',1),c=l('<h2 id="jvm-运行时的数据区域" tabindex="-1"><a class="header-anchor" href="#jvm-运行时的数据区域" aria-hidden="true">#</a> JVM 运行时的数据区域</h2><p>首先获取一个直观的认识：</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/LdgqY2.png" alt="JVM运行时的数据区域.png" tabindex="0" loading="lazy"><figcaption>JVM运行时的数据区域.png</figcaption></figure><p>总共也就这么 5 个区（直接内存不属于 JVM 运行时数据区的一部分），除了程序计数器其他的地方都有可能出现 OOM (OutOfMemoryError)，其中像是程序计数器和两个栈（Java 虚拟机栈 &amp; 本地方法栈）都是每个线程要有一个的，所以肯定是线程隔离的。而其他 2 个区就是线程共享的了，也就是说，如果有多个线程要同时访问这两个区的数据，是会出现线程安全问题的。接下来，我们将对这些区域进行详细的介绍。</p><h3 id="程序计数器" tabindex="-1"><a class="header-anchor" href="#程序计数器" aria-hidden="true">#</a> 程序计数器</h3><ul><li>当前线程所执行的字节码的行号指示器，字节码解释器工作时就是通过改变这个计数器的值来确定下一条要执行的字节码指令的位置</li><li>执行 Java 方法和 native 方法时的区别： <ul><li>执行 Java 方法时：记录虚拟机正在执行的字节码指令地址；</li><li>执行 native 方法时：无定义；</li></ul></li><li>是 5 个区域中唯一不会出现 OOM 的区域。</li></ul><h3 id="java-虚拟机栈" tabindex="-1"><a class="header-anchor" href="#java-虚拟机栈" aria-hidden="true">#</a> Java 虚拟机栈</h3><ul><li>Java 方法执行的内存模型，每个方法执行的过程，就是它所对应的栈帧在虚拟机栈中入栈到出栈的过程；</li><li>服务于 Java 方法；</li><li>可能抛出的异常： <ul><li>OutOfMemoryError（在虚拟机栈可以动态扩展的情况下，扩展时无法申请到足够的内存）；</li><li>StackOverflowError（线程请求的栈深度 &gt; 虚拟机所允许的深度）；</li></ul></li><li>虚拟机参数设置：<code>-Xss</code>.</li></ul><h3 id="本地方法栈" tabindex="-1"><a class="header-anchor" href="#本地方法栈" aria-hidden="true">#</a> 本地方法栈</h3><ul><li>服务于 native 方法；</li><li>可能抛出的异常：与 Java 虚拟机栈一样。</li></ul><h3 id="java-堆" tabindex="-1"><a class="header-anchor" href="#java-堆" aria-hidden="true">#</a> Java 堆</h3><ul><li>唯一的目的：存放对象实例；</li><li>垃圾收集器管理的主要区域；</li><li>可以处于物理上不连续的内存空间中；</li><li>可能抛出的异常： <ul><li>OutOfMemoryError（堆中没有内存可以分配给新创建的实例，并且堆也无法再继续扩展了）。</li></ul></li><li>虚拟机参数设置： <ul><li>最大值：<code>-Xmx</code></li><li>最小值：<code>-Xms</code></li><li>两个参数设置成相同的值可避免堆自动扩展。</li></ul></li></ul><h3 id="方法区" tabindex="-1"><a class="header-anchor" href="#方法区" aria-hidden="true">#</a> 方法区</h3><ul><li>存储已被虚拟机加载的类信息、常量、静态变量、即时编译器编译后的代码等数据； <ul><li>类信息：即 Class 类，如类名、访问修饰符、常量池、字段描述、方法描述等。</li></ul></li><li>垃圾收集行为在此区域很少发生； <ul><li>不过也不能不清理，对于经常动态生成大量 Class 的应用，如 Spring 等，需要特别注意类的回收状况。</li></ul></li><li>运行时常量池也是方法区的一部分； <ul><li>Class 文件中除了有类的版本、字段、方法、接口等描述信息外，还有一项是常量池，用于存放编译器生成的各种字面量（就是代码中定义的 static final 常量）和符号引用，这部分信息就存储在运行时常量池中。</li></ul></li><li>可能抛出的异常： <ul><li>OutOfMemoryError（方法区无法满足内存分配需求时）。</li></ul></li></ul><h3 id="直接内存" tabindex="-1"><a class="header-anchor" href="#直接内存" aria-hidden="true">#</a> 直接内存</h3><ul><li>JDK 1.4 的 NIO 类可以使用 native 函数库直接分配堆外内存，这是一种基于通道与缓冲区的 I/O 方式，它在 Java 堆中存储一个 DirectByteBuffer 对象作为堆外内存的引用，这样就可以对堆外内存进行操作了。因为可以避免 Java 堆和 Native 堆之间来回复制数据，在一些场景可以带来显著的性能提高。</li><li>虚拟机参数设置：<code>-XX:MaxDirectMemorySize</code><ul><li>默认等于 Java 堆最大值，即 <code>-Xmx</code> 指定的值。</li></ul></li><li>将直接内存放在这里讲解的原因是它也可能会出现 OutOfMemoryError； <ul><li>服务器管理员在配置 JVM 参数时，会根据机器的实际内存设置 <code>-Xmx</code> 等信息，但经常会忽略直接内存（默认等于 <code>-Xmx</code> 设置值），这可能会使得各个内存区域的总和大于物理内存限制，从而导致动态扩展时出现 OOM。</li></ul></li></ul><h2 id="hotspot-虚拟机堆中的对象" tabindex="-1"><a class="header-anchor" href="#hotspot-虚拟机堆中的对象" aria-hidden="true">#</a> HotSpot 虚拟机堆中的对象</h2><p>这一小节将对 JVM 对 Java 堆中的对象的创建、布局和访问的全过程进行讲解。</p><h3 id="对象的创建-遇到一条-new-指令时" tabindex="-1"><a class="header-anchor" href="#对象的创建-遇到一条-new-指令时" aria-hidden="true">#</a> 对象的创建（遇到一条 new 指令时）</h3><ol><li>检查这个指令的参数能否在常量池中定位到一个类的符号引用，并检查这个符号引用代表的类是否已被加载、解析和初始化过。如果没有，先把这个类加载进内存；</li><li>类加载检查通过后，虚拟机将为新对象分配内存，此时已经可以确定存储这个对象所需的内存大小；</li><li>在堆中为新对象分配可用内存；</li><li>将分配到的内存初始化；</li><li>设置对象头中的数据；</li><li>此时，从虚拟机的角度看，对象已经创建好了，但从 Java 程序的角度看，对象创建才刚刚开始，构造函数还没有执行。</li></ol><p>第 3 步，在堆中为新对象分配可用内存时，会涉及到以下两个问题：</p><p><strong>如何在堆中为新对象划分可用的内存？</strong></p><ul><li>指针碰撞（内存分配规整） <ul><li>用过的内存放一边，没用过的内存放一边，中间用一个指针分隔；</li><li>分配内存的过程就是将指针向没用过的内存那边移动所需的长度；</li></ul></li><li>空闲列表（内存分配不规整） <ul><li>维护一个列表，记录哪些内存块是可用的；</li><li>分配内存时，从列表上选取一块足够大的空间分给对象，并更新列表上的记录；</li></ul></li></ul><p><strong>如何处理多线程创建对象时，划分内存的指针的同步问题？</strong></p><ul><li>对分配内存空间的动作进行同步处理（CAS）；</li><li>把内存分配动作按照线程划分在不同的空间之中进行； <ul><li>每个线程在 Java 堆中预先分配一小块内存，称为本地线程分配缓冲（Thread Local Allocation Buffer，TLAB）；</li><li>哪个线程要分配内存就在哪个线程的 TLAB 上分配，TLAB 用完需要分配新的 TLAB 时，才需要同步锁定；</li><li>通过 <code>-XX:+/-UseTLAB</code> 参数设定是否使用 TLAB。</li></ul></li></ul><h3 id="对象的内存布局" tabindex="-1"><a class="header-anchor" href="#对象的内存布局" aria-hidden="true">#</a> 对象的内存布局</h3><ul><li>对象头： <ul><li>第一部分：存储对象自身运行时的数据，HashCode、GC分代年龄等（Mark Word）；</li><li>第二部分：类型指针，指向它的类元数据的指针，虚拟机通过这个指针来判断这个对象是哪个类的实例（HotSpot 采用的是直接指针的方式访问对象的）；</li><li>如果是个数组对象，对象头中还有一块用于记录数组长度的数据。</li></ul></li><li>实例数据： <ul><li>默认分配顺序：longs/doubles、ints、shorts/chars、bytes/booleans、oops (Ordinary Object Pointers)，相同宽度的字段会被分配在一起，除了 oops，其他的长度由长到短；</li><li>默认分配顺序下，父类字段会被分配在子类字段前面。</li></ul></li></ul><p><em>注：HotSpot VM要求对象的起始地址必须是8字节的整数倍，所以不够要补齐。</em></p><h3 id="对象的访问" tabindex="-1"><a class="header-anchor" href="#对象的访问" aria-hidden="true">#</a> 对象的访问</h3><p>Java 程序需要通过虚拟机栈上的 reference 数据来操作堆上的具体对象，reference 数据是一个指向对象的引用，不过如何通过这个引用定位到具体的对象，目前主要有以下两种访问方式：句柄访问和直接指针访问。</p><h4 id="句柄访问" tabindex="-1"><a class="header-anchor" href="#句柄访问" aria-hidden="true">#</a> 句柄访问</h4><p>句柄访问会在 Java 堆中划分一块内存作为句柄池，每一个句柄存放着到对象实例数据和对象类型数据的指针。</p><p>优势：对象移动的时候（这在垃圾回收时十分常见）只需改变句柄池中对象实例数据的指针，不需要修改reference本身。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/WjZq5i.png" alt="对象的访问定位_句柄访问.png" tabindex="0" loading="lazy"><figcaption>对象的访问定位_句柄访问.png</figcaption></figure><h4 id="直接指针访问" tabindex="-1"><a class="header-anchor" href="#直接指针访问" aria-hidden="true">#</a> 直接指针访问</h4><p>直接指针访问方式在 Java 堆对象的实例数据中存放了一个指向对象类型数据的指针，在 HotSpot 中，这个指针会被存放在对象头中。</p><p>优势：减少了一次指针定位对象实例数据的开销，速度更快。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/yYrIBs.png" alt="对象的访问定位_直接指针访问.png" tabindex="0" loading="lazy"><figcaption>对象的访问定位_直接指针访问.png</figcaption></figure><h1 id="oom-异常-outofmemoryerror" tabindex="-1"><a class="header-anchor" href="#oom-异常-outofmemoryerror" aria-hidden="true">#</a> OOM 异常 (OutOfMemoryError)</h1>',39),u=l('<ul><li><a href="#oom-%E5%BC%82%E5%B8%B8-outofmemoryerror">OOM 异常 (OutOfMemoryError)</a><ul><li><a href="#java-%E5%A0%86%E6%BA%A2%E5%87%BA">Java 堆溢出</a></li><li><a href="#java-%E8%99%9A%E6%8B%9F%E6%9C%BA%E6%A0%88%E5%92%8C%E6%9C%AC%E5%9C%B0%E6%96%B9%E6%B3%95%E6%A0%88%E6%BA%A2%E5%87%BA">Java 虚拟机栈和本地方法栈溢出</a></li><li><a href="#%E6%96%B9%E6%B3%95%E5%8C%BA%E5%92%8C%E8%BF%90%E8%A1%8C%E6%97%B6%E5%B8%B8%E9%87%8F%E6%B1%A0%E6%BA%A2%E5%87%BA">方法区和运行时常量池溢出</a></li><li><a href="#%E7%9B%B4%E6%8E%A5%E5%86%85%E5%AD%98%E6%BA%A2%E5%87%BA">直接内存溢出</a></li></ul></li></ul>',1),s=l('<h2 id="java-堆溢出" tabindex="-1"><a class="header-anchor" href="#java-堆溢出" aria-hidden="true">#</a> Java 堆溢出</h2><ul><li>出现标志：<code>java.lang.OutOfMemoryError: Java heap space</code></li><li>解决方法： <ul><li>先通过内存映像分析工具分析 Dump 出来的堆转储快照，确认内存中的对象是否是必要的，即分清楚是出现了内存泄漏还是内存溢出；</li><li>如果是内存泄漏，通过工具查看泄漏对象到 GC Root 的引用链，定位出泄漏的位置；</li><li>如果不存在泄漏，检查虚拟机堆参数（-Xmx 和 -Xms）是否可以调大，检查代码中是否有哪些对象的生命周期过长，尝试减少程序运行期的内存消耗。</li></ul></li><li>虚拟机参数： <ul><li><code>-XX:HeapDumpOnOutOfMemoryError</code>：让虚拟机在出现内存泄漏异常时 Dump 出当前的内存堆转储快照用于事后分析。</li></ul></li></ul><h2 id="java-虚拟机栈和本地方法栈溢出" tabindex="-1"><a class="header-anchor" href="#java-虚拟机栈和本地方法栈溢出" aria-hidden="true">#</a> Java 虚拟机栈和本地方法栈溢出</h2><ul><li>单线程下，栈帧过大、虚拟机容量过小都不会导致 OutOfMemoryError，只会导致 StackOverflowError（栈会比内存先爆掉），一般多线程才会出现 OutOfMemoryError，因为线程本身要占用内存；</li><li>如果是多线程导致的 OutOfMemoryError，在不能减少线程数或更换 64 位虚拟机的情况，只能通过减少最大堆和减少栈容量来换取更多的线程； <ul><li>这个调节思路和 Java 堆出现 OOM 正好相反，Java 堆出现 OOM 要调大堆内存的设置值，而栈出现 OOM 反而要调小。</li></ul></li></ul><h2 id="方法区和运行时常量池溢出" tabindex="-1"><a class="header-anchor" href="#方法区和运行时常量池溢出" aria-hidden="true">#</a> 方法区和运行时常量池溢出</h2><ul><li>测试思路：产生大量的类去填满方法区，直到溢出；</li><li>在经常动态生成大量 Class 的应用中，如 Spring 框架（使用 CGLib 字节码技术），方法区溢出是一种常见的内存溢出，要特别注意类的回收状况。</li></ul><h2 id="直接内存溢出" tabindex="-1"><a class="header-anchor" href="#直接内存溢出" aria-hidden="true">#</a> 直接内存溢出</h2><ul><li>出现特征：Heap Dump 文件中看不见明显异常，程序中直接或间接用了 NIO；</li><li>虚拟机参数：<code>-XX:MaxDirectMemorySize</code>，如果不指定，则和 <code>-Xmx</code> 一样。</li></ul><h1 id="垃圾收集-gc" tabindex="-1"><a class="header-anchor" href="#垃圾收集-gc" aria-hidden="true">#</a> 垃圾收集 (GC)</h1><p>垃圾收集（Garbage Collection，GC），它的任务是解决以下 3 件问题：</p><ul><li>哪些内存需要回收？</li><li>什么时候回收？</li><li>如何回收？</li></ul><p>其中第一个问题很好回答，在 Java 中，GC 主要发生在 Java 堆和方法区中，对于后两个问题，我们将在之后的内容中进行讨论，并介绍 HotSpot 的 7 个垃圾收集器。</p>',12),g=l('<ul><li><a href="#%E5%9E%83%E5%9C%BE%E6%94%B6%E9%9B%86-gc">垃圾收集 (GC)</a><ul><li><a href="#%E5%88%A4%E6%96%AD%E5%AF%B9%E8%B1%A1%E7%9A%84%E7%94%9F%E6%AD%BB">判断对象的生死</a><ul><li><a href="#%E5%88%A4%E6%96%AD%E5%AF%B9%E8%B1%A1%E6%98%AF%E5%90%A6%E5%8F%AF%E7%94%A8%E7%9A%84%E7%AE%97%E6%B3%95">判断对象是否可用的算法</a><ul><li><a href="#%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E7%AE%97%E6%B3%95">引用计数算法</a></li><li><a href="#%E5%8F%AF%E8%BE%BE%E6%80%A7%E5%88%86%E6%9E%90%E7%AE%97%E6%B3%95%E4%B8%BB%E6%B5%81">可达性分析算法（主流）</a></li></ul></li><li><a href="#%E5%9B%9B%E7%A7%8D%E5%BC%95%E7%94%A8%E7%B1%BB%E5%9E%8B">四种引用类型</a></li><li><a href="#%E5%AE%A3%E5%91%8A%E5%AF%B9%E8%B1%A1%E6%AD%BB%E4%BA%A1%E7%9A%84%E4%B8%A4%E6%AC%A1%E6%A0%87%E8%AE%B0%E8%BF%87%E7%A8%8B">宣告对象死亡的两次标记过程</a></li><li><a href="#%E6%96%B9%E6%B3%95%E5%8C%BA%E7%9A%84%E5%9B%9E%E6%94%B6">方法区的回收</a></li></ul></li><li><a href="#%E5%9E%83%E5%9C%BE%E6%94%B6%E9%9B%86%E7%AE%97%E6%B3%95">垃圾收集算法</a><ul><li><a href="#%E5%9F%BA%E7%A1%80%E6%A0%87%E8%AE%B0---%E6%B8%85%E9%99%A4%E7%AE%97%E6%B3%95">基础：标记 - 清除算法</a></li><li><a href="#%E8%A7%A3%E5%86%B3%E6%95%88%E7%8E%87%E9%97%AE%E9%A2%98%E5%A4%8D%E5%88%B6%E7%AE%97%E6%B3%95">解决效率问题：复制算法</a></li><li><a href="#%E8%A7%A3%E5%86%B3%E7%A9%BA%E9%97%B4%E7%A2%8E%E7%89%87%E9%97%AE%E9%A2%98%E6%A0%87%E8%AE%B0---%E6%95%B4%E7%90%86%E7%AE%97%E6%B3%95">解决空间碎片问题：标记 - 整理算法</a></li><li><a href="#%E8%BF%9B%E5%8C%96%E5%88%86%E4%BB%A3%E6%94%B6%E9%9B%86%E7%AE%97%E6%B3%95">进化：分代收集算法</a></li></ul></li><li><a href="#hotspot-%E4%B8%AD-gc-%E7%AE%97%E6%B3%95%E7%9A%84%E5%AE%9E%E7%8E%B0">HotSpot 中 GC 算法的实现</a></li><li><a href="#7-%E4%B8%AA%E5%9E%83%E5%9C%BE%E6%94%B6%E9%9B%86%E5%99%A8">7 个垃圾收集器</a><ul><li><a href="#serial--parnew-%E6%90%AD%E9%85%8D-serial-old-%E6%94%B6%E9%9B%86%E5%99%A8">Serial / ParNew 搭配 Serial Old 收集器</a></li><li><a href="#parallel-%E6%90%AD%E9%85%8D-parallel-scavenge-%E6%94%B6%E9%9B%86%E5%99%A8">Parallel 搭配 Parallel Scavenge 收集器</a></li><li><a href="#cms-%E6%94%B6%E9%9B%86%E5%99%A8">CMS 收集器</a></li><li><a href="#g1-%E6%94%B6%E9%9B%86%E5%99%A8">G1 收集器</a></li></ul></li><li><a href="#gc-%E6%97%A5%E5%BF%97%E8%A7%A3%E8%AF%BB">GC 日志解读</a></li></ul></li></ul>',1),p=l('<h2 id="判断对象的生死" tabindex="-1"><a class="header-anchor" href="#判断对象的生死" aria-hidden="true">#</a> 判断对象的生死</h2><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/KUyR2C.png" alt="判断对象的生死.png" tabindex="0" loading="lazy"><figcaption>判断对象的生死.png</figcaption></figure><p>什么时候回收对象？当然是这个对象再也不会被用到的时候回收。所以要想解决 “什么时候回收？” 这个问题，我们要先能判断一个对象什么时候什么时候真正的 “死” 掉了，判断对象是否可用主要有以下两种方法。</p><h3 id="判断对象是否可用的算法" tabindex="-1"><a class="header-anchor" href="#判断对象是否可用的算法" aria-hidden="true">#</a> 判断对象是否可用的算法</h3><h4 id="引用计数算法" tabindex="-1"><a class="header-anchor" href="#引用计数算法" aria-hidden="true">#</a> 引用计数算法</h4><ul><li><strong>算法描述：</strong><ul><li>给对象添加一个引用计数器；</li><li>每有一个地方引用它，计数器加 1；</li><li>引用失效时，计数器减 1；</li><li>计数器值为 0 的对象不再可用。</li></ul></li><li><strong>缺点：</strong><ul><li>很难解决循环引用的问题。即 <code>objA.instance = objB; objB.instance = objA;</code>，objA 和 objB 都不会再被访问后，它们仍然相互引用着对方，所以它们的引用计数器不为 0，将永远不能被判为不可用。</li></ul></li></ul><h4 id="可达性分析算法-主流" tabindex="-1"><a class="header-anchor" href="#可达性分析算法-主流" aria-hidden="true">#</a> 可达性分析算法（主流）</h4><ul><li><strong>算法描述：</strong><ul><li>从 &quot;GC Root&quot; 对象作为起点开始向下搜索，走过的路径称为引用链（Reference Chain）；</li><li>从 &quot;GC Root&quot; 开始，不可达的对象被判为不可用。</li></ul></li><li><strong>Java 中可作为 “GC Root” 的对象：</strong><ul><li>栈中（本地变量表中的reference） <ul><li>虚拟机栈中，栈帧中的本地变量表引用的对象；</li><li>本地方法栈中，JNI 引用的对象（native方法）；</li></ul></li><li>方法区中 <ul><li>类的静态属性引用的对象；</li><li>常量引用的对象；</li></ul></li></ul></li></ul><p>即便如此，一个对象也不是一旦被判为不可达，就立即死去的，宣告一个的死亡需要经过两次标记过程。</p><h3 id="四种引用类型" tabindex="-1"><a class="header-anchor" href="#四种引用类型" aria-hidden="true">#</a> 四种引用类型</h3><p>JDK 1.2 后，Java 中才有了后 3 种引用的实现。</p><ul><li><strong>强引用：</strong> 像 <code>Object obj = new Object()</code> 这种，只要强引用还存在，垃圾收集器就永远不会回收掉被引用的对象。</li><li><strong>软引用：</strong> 用来引用还存在但非必须的对象。对于软引用对象，在 OOM 前，虚拟机会把这些对象列入回收范围中进行第二次回收，如果这次回收后，内存还是不够用，就 OOM。实现类：<code>SoftReference</code>。</li><li><strong>弱引用：</strong> 被弱引用引用的对象只能生存到下一次垃圾收集前，一旦发生垃圾收集，被弱引用所引用的对象就会被清掉。实现类：<code>WeakReference</code>。</li><li><strong>虚引用：</strong> 幽灵引用，对对象没有半毛钱影响，甚至不能用来取得一个对象的实例。它唯一的用途就是：当被一个虚引用引用的对象被回收时，系统会收到这个对象被回收了的通知。实现类：<code>PhantomReference</code>。</li></ul><h3 id="宣告对象死亡的两次标记过程" tabindex="-1"><a class="header-anchor" href="#宣告对象死亡的两次标记过程" aria-hidden="true">#</a> 宣告对象死亡的两次标记过程</h3><ul><li>当发现对象不可达后，该对象被第一次标记，并进行是否有必要执行 <code>finalize()</code> 方法的判断； <ul><li>不需要执行：对象没有覆盖 <code>finalize()</code> 方法，或者 <code>finalize()</code> 方法已被执行过（<code>finalize()</code> 只被执行一次）；</li><li>需要执行：将该对象放置在一个队列中，稍后由一个虚拟机自动创建的低优先级线程执行。</li></ul></li><li><code>finalize()</code> 方法是对象逃脱死亡的最后一次机会，不过虚拟机不保证等待 <code>finalize()</code> 方法执行结束，也就是说，虚拟机只触发 <code>finalize()</code> 方法的执行，如果这个方法要执行超久，那么虚拟机并不等待它执行结束，所以最好不要用这个方法。</li><li><code>finalize()</code> 方法能做的，try-finally 都能做，所以忘了这个方法吧！</li></ul><h3 id="方法区的回收" tabindex="-1"><a class="header-anchor" href="#方法区的回收" aria-hidden="true">#</a> 方法区的回收</h3><p>永久代的 GC 主要回收：<strong>废弃常量</strong> 和 <strong>无用的类</strong>。</p><ul><li>废弃常量：例如一个字符串 &quot;abc&quot;，当没有任何引用指向 &quot;abc&quot; 时，它就是废弃常量了。</li><li>无用的类：同时满足以下 3 个条件的类。 <ul><li>该类的所有实例已被回收，Java 堆中不存在该类的任何实例；</li><li>加载该类的 Classloader 已被回收；</li><li>该类的 Class 对象没有被任何地方引用，即无法在任何地方通过反射访问该类的方法。</li></ul></li></ul><h2 id="垃圾收集算法" tabindex="-1"><a class="header-anchor" href="#垃圾收集算法" aria-hidden="true">#</a> 垃圾收集算法</h2><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/8Gudxz.png" alt="垃圾收集算法.png" tabindex="0" loading="lazy"><figcaption>垃圾收集算法.png</figcaption></figure><h3 id="基础-标记-清除算法" tabindex="-1"><a class="header-anchor" href="#基础-标记-清除算法" aria-hidden="true">#</a> 基础：标记 - 清除算法</h3><ul><li><strong>算法描述：</strong><ul><li>先标记出所有需要回收的对象（图中深色区域）；</li><li>标记完后，统一回收所有被标记对象（留下狗啃似的可用内存区域……）。</li></ul></li><li><strong>不足：</strong><ul><li>效率问题：标记和清理两个过程的效率都不高。</li><li>空间碎片问题：标记清除后会产生大量不连续的内存碎片，导致以后为较大的对象分配内存时找不到足够的连续内存，会提前触发另一次 GC。</li></ul></li></ul><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/aVAEDQ.png" alt="标记清除GC算法.png" tabindex="0" loading="lazy"><figcaption>标记清除GC算法.png</figcaption></figure><h3 id="解决效率问题-复制算法" tabindex="-1"><a class="header-anchor" href="#解决效率问题-复制算法" aria-hidden="true">#</a> 解决效率问题：复制算法</h3><ul><li><strong>算法描述：</strong><ul><li>将可用内存分为大小相等的两块，每次只使用其中一块；</li><li>当一块内存用完时，将这块内存上还存活的对象复制到另一块内存上去，将这一块内存全部清理掉。</li></ul></li><li><strong>不足：</strong> 可用内存缩小为原来的一半，适合GC过后只有少量对象存活的新生代。</li><li><strong>节省内存的方法：</strong><ul><li>新生代中的对象 98% 都是朝生夕死的，所以不需要按照 1:1 的比例对内存进行划分；</li><li>把内存划分为： <ul><li>1 块比较大的 Eden 区；</li><li>2 块较小的 Survivor 区；</li></ul></li><li>每次使用 Eden 区和 1 块 Survivor 区；</li><li>回收时，将以上 2 部分区域中的存活对象复制到另一块 Survivor 区中，然后将以上两部分区域清空；</li><li>JVM 参数设置：<code>-XX:SurvivorRatio=8</code> 表示 <code>Eden 区大小 / 1 块 Survivor 区大小 = 8</code>。</li></ul></li></ul><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/ZpuLSm.png" alt="复制GC算法.png" tabindex="0" loading="lazy"><figcaption>复制GC算法.png</figcaption></figure><h3 id="解决空间碎片问题-标记-整理算法" tabindex="-1"><a class="header-anchor" href="#解决空间碎片问题-标记-整理算法" aria-hidden="true">#</a> 解决空间碎片问题：标记 - 整理算法</h3><ul><li><strong>算法描述：</strong><ul><li>标记方法与 “标记 - 清除算法” 一样；</li><li>标记完后，将所有存活对象向一端移动，然后直接清理掉边界以外的内存。</li></ul></li><li><strong>不足：</strong> 存在效率问题，适合老年代。</li></ul><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/x0xsWz.png" alt="标记整理GC算法.png" tabindex="0" loading="lazy"><figcaption>标记整理GC算法.png</figcaption></figure><h3 id="进化-分代收集算法" tabindex="-1"><a class="header-anchor" href="#进化-分代收集算法" aria-hidden="true">#</a> 进化：分代收集算法</h3><ul><li><strong>新生代：</strong> GC 过后只有少量对象存活 —— <strong>复制算法</strong></li><li><strong>老年代：</strong> GC 过后对象存活率高 —— <strong>标记 - 整理算法</strong></li></ul><h2 id="hotspot-中-gc-算法的实现" tabindex="-1"><a class="header-anchor" href="#hotspot-中-gc-算法的实现" aria-hidden="true">#</a> HotSpot 中 GC 算法的实现</h2><p>通过前两小节对于判断对象生死和垃圾收集算法的介绍，我们已经对虚拟机是进行 GC 的流程有了一个大致的了解。但是，在 HotSpot 虚拟机中，高效的实现这些算法也是一个需要考虑的问题。所以，接下来，我们将研究一下 HotSpot 虚拟机到底是如何高效的实现这些算法的，以及在实现中有哪些需要注意的问题。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/J96sfB.png" alt="GC的算法实现.png" tabindex="0" loading="lazy"><figcaption>GC的算法实现.png</figcaption></figure><p>通过之前的分析，GC 算法的实现流程简单的来说分为以下两步：</p><ol><li>找到死掉的对象；</li><li>把它清了。</li></ol><p>想要找到死掉的对象，我们就要进行可达性分析，也就是从 GC Root 找到引用链的这个操作。</p><p>也就是说，进行可达性分析的第一步，就是要枚举 GC Roots，这就需要虚拟机知道哪些地方存放着对象应用。如果每一次枚举 GC Roots 都需要把整个栈上位置都遍历一遍，那可就费时间了，毕竟并不是所有位置都存放在引用呀。所以为了提高 GC 的效率，HotSpot 使用了一种 OopMap 的数据结构，<strong>OopMap 记录了栈上本地变量到堆上对象的引用关系</strong>，也就是说，GC 的时候就不用遍历整个栈只遍历每个栈的 OopMap 就行了。</p><p>在 OopMap 的帮助下，HotSpot 可以快速准确的完成 GC 枚举了，不过，OopMap 也不是万年不变的，它也是需要被更新的，当内存中的对象间的引用关系发生变化时，就需要改变 OopMap 中的相应内容。可是能导致引用关系发生变化的指令非常之多，如果我们执行完一条指令就改下 OopMap，这 GC 成本实在太高了。</p><p>因此，HotSpot 采用了一种在 “安全点” 更新 OopMap 的方法，安全点的选取既不能让 GC 等待的时间过长，也不能过于频繁增加运行负担，也就是说，我们既要让程序运行一段时间，又不能让这个时间太长。我们知道，JVM 中每条指令执行的是很快的，所以一个超级长的指令流也可能很快就执行完了，所以 <strong>真正会出现 “长时间执行” 的一般是指令的复用，例如：方法调用、循环跳转、异常跳转等</strong>，虚拟机一般会将这些地方设置为安全点更新 OopMap 并判断是否需要进行 GC 操作。</p><p>此外，在进行枚举根节点的这个操作时，为了保证准确性，我们需要在一段时间内 “冻结” 整个应用，即 Stop The World（传说中的 GC 停顿），因为如果在我们分析可达性的过程中，对象的引用关系还在变来变去，那是不可能得到正确的分析结果的。即便是在号称几乎不会发生停顿的 CMS 垃圾收集器中，枚举根节点时也是必须要停顿的。这里就涉及到了一个问题：</p><p><strong>我们让所有线程跑到最近的安全点再停顿下来进行 GC 操作呢？</strong></p><p>主要有以下两种方式：</p><ul><li>抢先式中断： <ul><li>先中断所有线程；</li><li>发现有线程没中断在安全点，恢复它，让它跑到安全点。</li></ul></li><li><strong>主动式中断：</strong> (主要使用) <ul><li>设置一个中断标记；</li><li>每个线程到达安全点时，检查这个中断标记，选择是否中断自己。</li></ul></li></ul><p>除此安全点之外，还有一个叫做 “安全区域” 的东西，一个一直在执行的线程可以自己 “走” 到安全点去，可是一个处于 Sleep 或者 Blocked 状态的线程是没办法自己到达安全点中断自己的，我们总不能让 GC 操作一直等着这些个 ”不执行“ 的线程重新被分配资源吧。对于这种情况，我们要依靠安全区域来解决。</p><p><strong>安全区域是指在一段代码片段之中，引用关系不会发生变化，因此在这个区域中的任意位置开始 GC 都是安全的。</strong></p><p>当线程执行到安全区域时，它会把自己标识为 Safe Region，这样 JVM 发起 GC 时是不会理会这个线程的。当这个线程要离开安全区域时，它会检查系统是否在 GC 中，如果不在，它就继续执行，如果在，它就等 GC 结束再继续执行。</p><p>本小节我们主要讲述 HotSpot 虚拟机是如何发起内存回收的，也就是如何找到死掉的对象，至于如何清掉这些个对象，HotSpot 将其交给了一堆叫做 ”GC 收集器“ 的东西，这东西又有好多种，不同的 GC 收集器的处理方式不同，适用的场景也不同，我们将在下一小节进行详细讲述。</p><h2 id="_7-个垃圾收集器" tabindex="-1"><a class="header-anchor" href="#_7-个垃圾收集器" aria-hidden="true">#</a> 7 个垃圾收集器</h2><p>垃圾收集器就是内存回收操作的具体实现，HotSpot 里足足有 7 种，为啥要弄这么多，因为它们各有各的适用场景。有的属于新生代收集器，有的属于老年代收集器，所以一般是搭配使用的（除了万能的 G1）。关于它们的简单介绍以及分类请见下图。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/HzHvnP.png" alt="垃圾收集器们.png" tabindex="0" loading="lazy"><figcaption>垃圾收集器们.png</figcaption></figure><h3 id="serial-parnew-搭配-serial-old-收集器" tabindex="-1"><a class="header-anchor" href="#serial-parnew-搭配-serial-old-收集器" aria-hidden="true">#</a> Serial / ParNew 搭配 Serial Old 收集器</h3><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/AYLiHx.jpg" alt="Serial_ParNew收集器.jpg" tabindex="0" loading="lazy"><figcaption>Serial_ParNew收集器.jpg</figcaption></figure><p>Serial 收集器是虚拟机在 Client 模式下的默认新生代收集器，它的优势是简单高效，在单 CPU 模式下很牛。</p><p>ParNew 收集器就是 Serial 收集器的多线程版本，虽然除此之外没什么创新之处，但它却是许多运行在 Server 模式下的虚拟机中的首选新生代收集器，因为除了 Serial 收集器外，只有它能和 CMS 收集器搭配使用。</p><h3 id="parallel-搭配-parallel-scavenge-收集器" tabindex="-1"><a class="header-anchor" href="#parallel-搭配-parallel-scavenge-收集器" aria-hidden="true">#</a> Parallel 搭配 Parallel Scavenge 收集器</h3><p>首先，这俩货肯定是要搭配使用的，不仅仅如此，它俩还贼特别，它们的关注点与其他收集器不同，其他收集器关注于尽可能缩短垃圾收集时用户线程的停顿时间，而 Parallel Scavenge 收集器的目的是达到一个可控的吞吐量。</p><blockquote><p>吞吐量 = 运行用户代码时间 / ( 运行用户代码时间 + 垃圾收集时间 )</p></blockquote><p>因此，Parallel Scavenge 收集器不管是新生代还是老年代都是多个线程同时进行垃圾收集，十分适合于应用在注重吞吐量以及 CPU 资源敏感的场合。</p><p>可调节的虚拟机参数：</p><ul><li><code>-XX:MaxGCPauseMillis</code>：最大 GC 停顿的秒数；</li><li><code>-XX:GCTimeRatio</code>：吞吐量大小，一个 0 ~ 100 的数，<code>最大 GC 时间占总时间的比率 = 1 / (GCTimeRatio + 1)</code>；</li><li><code>-XX:+UseAdaptiveSizePolicy</code>：一个开关参数，打开后就无需手工指定 <code>-Xmn</code>，<code>-XX:SurvivorRatio</code> 等参数了，虚拟机会根据当前系统的运行情况收集性能监控信息，自行调整。</li></ul><h3 id="cms-收集器" tabindex="-1"><a class="header-anchor" href="#cms-收集器" aria-hidden="true">#</a> CMS 收集器</h3><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/HkUdne.png" alt="CMS垃圾收集器.png" tabindex="0" loading="lazy"><figcaption>CMS垃圾收集器.png</figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/xHKbh9.jpg" alt="CMS收集器运行示意图.jpg" tabindex="0" loading="lazy"><figcaption>CMS收集器运行示意图.jpg</figcaption></figure><p><strong>参数设置：</strong></p><ul><li><code>-XX:+UseCMSCompactAtFullCollection</code>：在 CMS 要进行 Full GC 时进行内存碎片整理（默认开启）</li><li><code>-XX:CMSFullGCsBeforeCompaction</code>：在多少次 Full GC 后进行一次空间整理（默认是 0，即每一次 Full GC 后都进行一次空间整理）</li></ul><blockquote><p><strong>关于 CMS 使用 标记 - 清除 算法的一点思考：</strong></p><p>之前对于 CMS 为什么要采用 标记 - 清除 算法十分的不理解，既然已经有了看起来更高级的 标记 - 整理 算法，那 CMS 为什么不用呢？最近想了想，感觉可能是这个原因，不过也不是很确定，只是个人的一种猜测。</p><p>标记 - 整理 会将所有存活对象向一端移动，然后直接清理掉边界以外的内存。这就意味着需要一个指针来维护这个分隔存活对象和无用空间的点，而我们知道 CMS 是并发清理的，虽然我们启动了多个线程进行垃圾回收，不过如果使用 标记 - 整理 算法，为了保证线程安全，在整理时要对那个分隔指针加锁，保证同一时刻只有一个线程能修改它，<strong>加锁的这一过程相当于将并行的清理过程变成了串行的，也就失去了并行清理的意义了。</strong></p><p>所以，CMS 采用了 标记 - 清除 算法。</p></blockquote><h3 id="g1-收集器" tabindex="-1"><a class="header-anchor" href="#g1-收集器" aria-hidden="true">#</a> G1 收集器</h3><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/DaS5ty.png" alt="G1垃圾收集器.png" tabindex="0" loading="lazy"><figcaption>G1垃圾收集器.png</figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/GSTIO2.jpg" alt="G1收集器运行示意图.jpg" tabindex="0" loading="lazy"><figcaption>G1收集器运行示意图.jpg</figcaption></figure><h2 id="gc-日志解读" tabindex="-1"><a class="header-anchor" href="#gc-日志解读" aria-hidden="true">#</a> GC 日志解读</h2><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/08/18/MEfSZY.png" alt="GC日志解读.png" tabindex="0" loading="lazy"><figcaption>GC日志解读.png</figcaption></figure>',71);function f(A,B){return o(),t("div",null,[d,h,i(" TOC "),E,i(" /TOC "),c,i(" TOC "),u,i(" /TOC "),s,i(" TOC "),g,i(" /TOC "),p])}const v=r(n,[["render",f],["__file","notes.html.vue"]]);export{v as default};
